struct TransitionTrack { int first_value, second_value, current_value, step_delta, duration_ticks, auxiliary; };
struct TransitionSpritePath {
    int x_first, x_target, x_current, x_step_delta, x_duration;
    unsigned char *sprite_offset;
    int y_first, y_target, y_current, y_step_delta, y_duration, y_auxiliary;
};
struct BobFrameMetrics { short prefix, width, height; int opaque_06; short x_offset, y_offset; int opaque_0e; };
struct IntRect { int left, top, right, bottom; };
struct SpriteDrawCommand { int sprite_or_frame; short x, y, flags; };
extern struct BobFrameMetrics *sprite_metadata;
extern short x_delta;
extern short y_offset;
extern short width;
extern short height;
