/* These globals save the draw cursor and count work during transition frames. */
extern int save_cur;
extern short retrace_tick_count;
extern short ticklim;
extern unsigned char current_scan_code;
extern unsigned char prior_key_ascii;
extern unsigned char keyboard_scan_byte;
extern unsigned char current_ascii;
extern void handle_s_key(void);
/* Legacy frame hook called once before each transition draw. */
extern void wait_for_tick(unsigned char);
extern void redraw_image_region(int, int);
extern void show_page(void);

void init_tracks(void)
{
    struct TransitionTrack *track = transition_track_data;
    int track_index = 0;
    for (; track_index < path_count; track_index++) {
        track->step_delta = (track->second_value - track->first_value) / track->duration_ticks;
        track->current_value = track->first_value - track->step_delta;
        track++;
    }
    tick = 0;
}

void advance_tracks(void)
{
    struct TransitionTrack *track;
    int track_index;
    ++tick;
    track = transition_track_data;
    track_index = 0;
    for (; track_index < path_count; track_index++) {
        if (tick >= track->duration_ticks)
            track->current_value = track->second_value;
        else
            track->current_value += track->step_delta;
        track++;
    }
}

void queue_draws(void)
{
    struct TransitionSpritePath *path = (struct TransitionSpritePath *)transition_track_data;
    int path_index = 0;
    for (; path_index < (path_count >> 1); path_index++) {
        image_buffer_cursor->sprite_or_frame = (unsigned)(path->sprite_offset + sprite_base);
        image_buffer_cursor->x = (short)(path->x_current >> 4);
        image_buffer_cursor->y = (short)(path->y_current >> 4);
        image_buffer_cursor->flags = 0;
        image_buffer_cursor++;
        ++path;
    }
}

void set_page(void)
{
    set_image_pages((int)sprite_commands, 0x100, 4, (int)front_page_bufs, (int)back_page_queue);
    page_idx = src_page;
    drawpage = dst_page;
    page2 = stored_page_2_index;
    page3 = page_3;
}

void await_input(int frame_limit)
{
    space_pressed = 0;
    hook_flags_word = (hook_flags_word & 0xfffe) & 0xfffd;
    do {
        wait_for_tick(3);
        retrace_tick_count = 0;
        save_cur = (int)image_buffer_cursor;
        do {
            image_buffer_cursor = (struct SpriteDrawCommand *)save_cur;
            handle_s_key();
            advance_tracks();
            queue_draws();
            ++retrace_tick_count;
        } while (retrace_tick_count < ticklim);
        redraw_image_region(0, 0);
        show_page();
    } while ((prior_key_ascii == current_ascii || current_ascii != 0x20) && (mouse_btn == mouse_btn_old || !(*(unsigned char *)&mouse_btn & 7)) && (current_scan_code == keyboard_scan_byte || keyboard_scan_byte != 1) && tick < frame_limit);
}
